#!/usr/bin/env python3
"""Find AI attribution in commit messages and pull-request text.

Usage: attribution.py   (in a GitHub Actions pull_request run)
Checks the PR's commits (git log BASE..HEAD), title, body and branch name from
$GITHUB_EVENT_PATH. Commit messages and the title land on main (squash merges
copy every commit message and add a co-author trailer for every other commit
author), so a hit there or an AI commit identity fails a same-repository PR; a fork
PR only gets warnings, which the owner clears from the squash message at merge.
Body and branch hits are warnings: the branch is deleted at merge, and some
agent platforms re-append a body footer that no edit can remove.
The review runner imports `findings`; public repositories vendor this file as
.github/scripts/attribution.py. Policy: wiki workflows/attribution.md.
Stdlib only.
"""

import json
import os
import re
import subprocess
import sys

TRAILER_TOOLS = (
    r"claude|anthropic|openai|chatgpt|codex|copilot|gemini|jules|cursor|devin|"
    r"aider|windsurf|codeium|openclaw|amazon[ _-]?q|kiro"
)
# Product names that never name a person; sign-offs and identities share them.
PRODUCTS = (
    r"(?:github )?copilot|(?:anthropic(?:'s)? )?claude code|anthropic(?:'s)? claude|"
    r"(?:openai )?codex(?: cli)?|chatgpt|(?:google )?gemini (?:cli|code assist)|"
    r"google gemini|google jules|cursor (?:agent|ai)|devin ai|kiro agent|"
    r"amazon q(?: developer)?|aider|windsurf|codeium|openclaw|"
    r"(?:openai )?gpt-\d[a-z0-9]*(?:[.-][a-z0-9]+)*"
)
MODELS = r"opus|sonnet|haiku|pro|flash|ultra|mini|nano"
# A model as the whole credit: an optional capitalised name, then a version
# that is not a year ("Claude Fable 5.1", "Gemini 2.5 Pro"), or only tier
# words ("Claude Sonnet"); not "Jules Martin in 2019" or "Devin for v2".
VERSION = r"v?(?!\d{4}\b)\d+(?:\.\d+)*"
MODEL = (
    rf"(?:[ \t]+(?:{MODELS}|(?-i:[A-Z][a-z]+)))?[ \t]*{VERSION}(?:[ \t]+(?:{MODELS}))?"
    rf"|(?:[ \t]+(?:{MODELS}))+"
)
# A credit is the whole rest of its line or parenthesis, or meets an email or a
# link: "Generated by Codex.", "Generated with [Claude Code](https://...)", not
# "(created by Codex before 0.5)" or "Co-authored by Devin, Sam and Alex".
CREDIT_END = r"[ \t]*(?:[.!)\]]+[ \t]*)?$|[ \t]*<|[ \t]*\]?\(https?://"
L, R = r"(?<![a-z0-9])", r"(?![a-z0-9])"
# A product may carry a model, a version or a parenthesis: "Claude Code (Opus
# 4.5)", "Codex CLI v0.46", "aider (gpt-5)". A name people also have takes a
# parenthesis only after a model: "Claude Opus 5 (1M context)", not "Jules
# (my colleague)".
PRODUCT_TAIL = rf"(?:{MODEL})?(?:[ \t]*\([^()\n]*\))?"
NAME_TAIL = rf"(?:(?:{MODEL})(?:[ \t]*\([^()\n]*\))?)?"
WRITERS = (
    # A product ends at a word edge, so a long version or digit run is not
    # rescanned from every position inside it.
    rf"(?:{PRODUCTS}){R}(?={PRODUCT_TAIL}(?:{CREDIT_END}))|"
    rf"(?:an? (?:ai|llm)(?: agent| assistant| model)?"
    rf"|anthropic|openai|google|cursor)(?={CREDIT_END})|"
    # "Written with Claude Opus 5", not "Written by Claude Dupont".
    rf"(?:claude|gemini|jules|devin|kiro)(?={NAME_TAIL}(?:{CREDIT_END}))"
)
# Emphasis and code marks at word edges, so "_Generated by **Claude Code**_"
# reads as plain text; underscores inside words stay.
MARKUP = re.compile(r"[*_`~]+")
WORD = re.compile(r"\w")
# A sign-off starts a paragraph, after any markup or emoji ("🤖 Generated
# with"), or follows a separator in a title ("Fix parser — Generated by Codex").
# Prose such as "Parse output generated by Codex", hard-wrapped or not, is not
# one. findings() blanks rule lines, so "---" before a footer is a paragraph
# break. Indentation is free only at the start; the marks after any start are
# bounded and taken whole, since an unbounded run backtracks from every
# separator in a line of punctuation, which is quadratic in the line.
LEAD = (
    r"(?:(?:\A|(?<=\n\n))[ \t]*(?![ \t])|[\u2014\u2013|(;]|[ \t]-[ \t])"
    r"[^\w\n]{0,16}(?![^\w\n])"
)
# The value is split in code: nested optional whitespace in one pattern
# backtracks polynomially on a long run of spaces.
TRAILER = re.compile(
    r"^[ \t]*(?:co-authored-by|signed-off-by|reviewed-by|helped-by)[ \t]*:"
    r"(?P<value>[^\n]*)",
    re.I | re.M,
)
RULE = re.compile(r"[ \t]*(?:-{3,}|\*{3,}|_{3,})")
# Lines are cut to this length before matching. No real sign-off is this long.
LINE_CHARS = 1000
PATTERNS = (
    # Trailer keys that only exist to credit a tool.
    re.compile(
        r"^[ \t]*(?:(?:assisted|generated|ai-assisted|ai-generated)-by|made-with)"
        r"[ \t]*:[^\n]*",
        re.I | re.M,
    ),
    # Compound credits as the whole credit: "Claude-assisted change", not
    # "Codex-generated sessions are pruned". Not "AI-generated", which also
    # names product features.
    re.compile(
        rf"{LEAD}(?:{TRAILER_TOOLS})[ \t]*-[ \t]*(?:generated|assisted|written"
        r"|authored|created|drafted)"
        r"(?:[ \t]+(?:change|commit|patch|code|fix|update|pr|docs|tests?))?"
        rf"(?={CREDIT_END})[^\n]*",
        re.I | re.M,
    ),
    # Agent session and task links.
    re.compile(
        r"https?://(?:www\.)?(?:claude\.ai/code|claude\.com/claude-code|"
        r"chatgpt\.com/codex|github\.com/copilot/tasks|jules\.google(?:\.com)?|"
        r"app\.devin\.ai)\S*",
        re.I,
    ),
)
# Sign-offs: "Generated with [Claude Code](...)", "Implemented by Codex". A
# credit to `name <email>` counts only for a tool's identity.
SIGNOFF = re.compile(
    rf"{LEAD}(?:generated|created|made|written|authored|co-authored|produced"
    r"|drafted|implemented|coded|assisted)[ \t]+(?:with|by|using|via):?[ \t]+"
    rf"(?:\[|the[ \t]+)?(?P<who>{WRITERS}){R}(?:[ \t]*<(?P<email>[^<>\n]*)>)?[^\n]*",
    re.I | re.M,
)
# Identities only in a tool's own forms, so people named Claude, Devin or Jules,
# and people at these companies, are not caught; a bare "Claude" counts only
# with a tool's email.
TOOL_NAME = re.compile(
    # aider marks its commits by default as "Jane Doe (aider)".
    rf"(?:{PRODUCTS}){PRODUCT_TAIL}|(?:{TRAILER_TOOLS})[ _-]?(?:bot|agent)|"
    r"[^()]*\(aider\)|"
    rf"[\w.-]*{L}(?:{TRAILER_TOOLS}){R}[\w.-]*\[bot\]",
    re.I,
)
# "bot" or "agent" as its own word of the local part, so talbot@ is a person.
TOOL_LOCAL = r"(?:no-?reply|(?:[\w.-]*[._-]|cursor)?(?:bot|agent))"
TOOL_EMAIL = re.compile(
    rf"{TOOL_LOCAL}@(?:[\w-]+\.)*"
    r"(?:anthropic\.com|openai\.com|cursor\.com|aider\.chat|windsurf\.com|"
    r"codeium\.com|devin\.ai)|\d+\+[^@]*@users\.noreply\.github\.com",
    re.I,
)
# A bare tool name, with any model and version, as in a trailer with no email
# or a no-reply one: "Claude Opus 5.5 (1M context)", "Gemini <noreply@...>".
BARE_TOOL = re.compile(
    rf"(?:{TRAILER_TOOLS}|gpt-\d[\w.-]*)(?:(?:{MODEL})(?:[ \t]*\([^()]*\))?)?",
    re.I,
)
TOOL_ADDRESS = re.compile(rf"{TOOL_LOCAL}@[^@]+", re.I)
BRANCH = re.compile(
    rf"^(?:{TRAILER_TOOLS.replace('amazon[ _-]?q|', '')}|ai)[/_-]", re.I
)


def findings(text):
    """The attribution snippets in text, in order of appearance; a hit inside an
    earlier one (a footer's session link) is not repeated."""
    lines = (text or "").replace("\r\n", "\n").replace("\r", "\n").split("\n")
    lines = (
        "" if RULE.fullmatch(line) else line
        for line in (line[:LINE_CHARS].rstrip() for line in lines)
    )
    text = unmark("\n".join(lines))
    trailers = TRAILER.finditer(text)
    matches = [m for m in trailers if ai_identity(*trailer_identity(m["value"]))]
    matches += [
        m
        for m in SIGNOFF.finditer(text)
        if m["email"] is None or ai_identity(m["who"], m["email"])
    ]
    matches += [m for p in PATTERNS for m in p.finditer(text)]
    hits, end = [], 0
    for m in sorted(matches, key=lambda m: (m.start(), -m.end())):
        if m.start() >= end:
            hits.append(m.group(0).strip()[:120])
            end = m.end()
    return hits


def unmark(text):
    """Drop every run of marks not between two word characters. Each run is
    judged once, since a lookaround regex backtracks through a long run."""

    def keep(m):
        start, end = m.span()
        inside = (
            0 < start
            and end < len(text)
            and WORD.match(text[start - 1])
            and WORD.match(text[end])
        )
        return m[0] if inside else ""

    return MARKUP.sub(keep, text)


def trailer_identity(value):
    """(name, email) from a trailer value such as `Name <email>`."""
    name, _, rest = value.partition("<")
    email, closed, _ = rest.partition(">")
    return name.strip(), email.strip() if closed else None


def ai_identity(name, email):
    """True when a commit author, committer or co-author is an AI tool, not a
    person. A GitHub noreply address counts only for a tool's own user name."""
    # Capped like findings' lines: TOOL_NAME rescans the rest of the name from
    # every tool word, so an unbounded name costs quadratic time.
    name, email = (name or "").strip()[:200], (email or "").strip()[:200]
    if TOOL_NAME.fullmatch(name):
        return True
    if BARE_TOOL.fullmatch(name) and (not email or TOOL_ADDRESS.fullmatch(email)):
        return True
    if not TOOL_EMAIL.fullmatch(email):
        return False
    login = email.split("@")[0].split("+")[-1]
    return "noreply.github.com" not in email or bool(TOOL_NAME.fullmatch(login))


def ai_branch(name):
    return bool(BRANCH.match(name or ""))


def commits(base, head, number):
    """(sha, author/committer identities, message) for base..head.

    Fetches only commit objects, no trees or blobs.
    """
    subprocess.run(
        [
            "git",
            "fetch",
            "--no-tags",
            "--quiet",
            "--filter=tree:0",
            "origin",
            base,
            f"+refs/pull/{number}/head:refs/remotes/attribution/head",
        ],
        check=True,
    )
    # Six NUL-separated fields per commit; a message can hold any byte but NUL.
    fields = subprocess.run(
        [
            "git",
            "log",
            "-z",
            "--format=%H%x00%an%x00%ae%x00%cn%x00%ce%x00%B",
            f"{base}..{head}",
        ],
        check=True,
        capture_output=True,
        text=True,
    ).stdout.split("\0")
    entries = [fields[i : i + 6] for i in range(0, len(fields) - 5, 6)]
    return [
        (sha, ((an, ae), (cn, ce)), message) for sha, an, ae, cn, ce, message in entries
    ]


def main():
    with open(os.environ["GITHUB_EVENT_PATH"], encoding="utf-8") as event:
        pr = json.load(event).get("pull_request")
    if not pr:
        print("attribution: not a pull request; nothing to check")
        return 0
    blocking = []
    for sha, identities, message in commits(
        pr["base"]["sha"], pr["head"]["sha"], pr["number"]
    ):
        blocking += [(f"commit {sha[:12]}", hit) for hit in findings(message)]
        blocking += [
            (f"commit {sha[:12]} identity", f"{name} <{email}>")
            for name, email in dict.fromkeys(identities)
            if ai_identity(name, email)
        ]
    blocking += [("PR title", hit) for hit in findings(pr["title"])]
    notes = [("PR description", hit) for hit in findings(pr.get("body"))]
    if ai_branch(pr["head"]["ref"]):
        notes.append(("branch name", pr["head"]["ref"]))
    fork = (pr["head"].get("repo") or {}).get("full_name") != pr["base"]["repo"][
        "full_name"
    ]
    for where, hit in blocking:
        print(f"::{'warning' if fork else 'error'}::AI attribution in {where}: {hit}")
    for where, hit in notes:
        print(f"::warning::AI attribution in {where}: {hit}")
    if blocking and not fork:
        print("attribution: reword the commits or title (policy: no AI attribution).")
        return 1
    print("attribution: ok")
    return 0


if __name__ == "__main__":
    sys.exit(main())
